	switch string(lower[:len(name)]) {
	case "origin":
		return "origin"
	case "active":
		return "active"
	}
	return name
zjUnicode:
	if strings_.EqualFold(name, "origin") {
		return "origin"
	}
	if strings_.EqualFold(name, "active") {
		return "active"
	}
	return name
